from pathlib import Path
import re
root=Path('/mnt/data/gamesarena_work')

# server.js
p=root/'server.js'; s=p.read_text()
# replace fastest word helper block
start=s.index('const FASTEST_WORDS = [')
end=s.index('function makeRoom()', start)
new='''const FASTEST_SEQUENCE_TIME_MS = 15000;\nfunction makeFastestSequence(){\n  // Hard, game-show-style ordering challenge. All selected players receive\n  // the same sequence so the result is based on speed and accuracy.\n  const count=8;\n  const values=new Set();\n  while(values.size<count) values.add(Math.floor(100+Math.random()*900));\n  const items=[...values].sort(()=>Math.random()-.5).map((value,id)=>({id,value}));\n  const answerIds=[...items].sort((a,b)=>a.value-b.value).map(item=>item.id);\n  return {difficulty:"HARD",direction:"LOWEST → HIGHEST",items,answerIds};\n}\n\n'''
s=s[:start]+new+s[end:]
# room fields
s=s.replace('fastestDurationMs:10000,fastestSequence:[],fastestWordAnswer:"",fastestWordScrambled:"",fastestTimes', 'fastestDurationMs:FASTEST_SEQUENCE_TIME_MS,fastestSequence:[],fastestSequenceAnswer:[],fastestSequenceDifficulty:"HARD",fastestSequenceDirection:"LOWEST → HIGHEST",fastestWordAnswer:"",fastestWordScrambled:"",fastestTimes')
# emit state fields
s=s.replace('fastestSequence:r.fastestSequence,fastestWordScrambled:r.fastestWordScrambled,fastestWordLength:r.fastestWordAnswer.length,', 'fastestSequence:r.fastestSequence,fastestSequenceAnswer:r.fastestSequenceAnswer,fastestSequenceDifficulty:r.fastestSequenceDifficulty,fastestSequenceDirection:r.fastestSequenceDirection,fastestWordScrambled:r.fastestWordScrambled,fastestWordLength:r.fastestWordAnswer.length,')
# startFastest generation
old=''' const fastestWord=chooseFastestWord();\n r.fastestWordAnswer=fastestWord.answer;\n r.fastestWordScrambled=fastestWord.scrambled;\n r.fastestSequence=[];\n'''
new=''' const challenge=makeFastestSequence();\n r.fastestSequence=challenge.items;\n r.fastestSequenceAnswer=challenge.answerIds;\n r.fastestSequenceDifficulty=challenge.difficulty;\n r.fastestSequenceDirection=challenge.direction;\n r.fastestWordAnswer="";\n r.fastestWordScrambled="";\n r.fastestDurationMs=FASTEST_SEQUENCE_TIME_MS;\n'''
if old not in s: raise SystemExit('start generation block not found')
s=s.replace(old,new)
# replace submit listener
st=s.index(' s.on("fastest:submitWord"')
en=s.index(' s.on("host:startQuiz"', st)
new_listener=''' s.on("fastest:submitSequence",({index}={})=>{\n  const r=rooms.get(s.data.room);\n  if(!r||r.phase!=="fastest")return;\n  const u=r.users.get(s.id);\n  if(!u||u.status!=="active"||!r.pool.some(p=>p.id===s.id))return;\n  const now=Date.now();\n  if(now<r.fastestStartAt||now>r.fastestStartAt+r.fastestDurationMs)return;\n  if(r.winner)return;\n  const itemIndex=Number(index);\n  const item=r.fastestSequence[itemIndex];\n  if(!item)return;\n  let p=r.fastestProgress.get(u.employeeCode);\n  if(!p){\n    p={name:u.name,submitted:"",sequence:[],time:0,status:"READY",attempts:0};\n    r.fastestProgress.set(u.employeeCode,p);\n  }\n  const elapsed=now-r.fastestStartAt;\n  p.attempts=Number(p.attempts||0)+1;\n  const expectedId=r.fastestSequenceAnswer[p.sequence.length];\n  if(itemIndex!==expectedId){\n    p.submitted=String(item.value);\n    p.time=elapsed;\n    p.status="WRONG";\n    s.emit("fastestSequenceResult",{correct:false,elapsed,attempts:p.attempts,progress:p.sequence.length});\n    emitState(s.data.room);\n    return;\n  }\n  p.sequence.push(itemIndex);\n  p.submitted=String(item.value);\n  p.time=elapsed;\n  p.status=p.sequence.length===r.fastestSequenceAnswer.length?"COMPLETED":"PROGRESS";\n  if(p.sequence.length<r.fastestSequenceAnswer.length){\n    s.emit("fastestSequenceResult",{correct:true,elapsed,progress:p.sequence.length,total:r.fastestSequenceAnswer.length});\n    emitState(s.data.room);\n    return;\n  }\n  r.fastestTimes.set(u.employeeCode,{name:u.name,time:elapsed,status:"COMPLETED"});\n  s.emit("fastestSequenceResult",{correct:true,elapsed,progress:p.sequence.length,total:r.fastestSequenceAnswer.length,complete:true});\n  if(!r.winner){\n    r.winner={...u,time:elapsed};\n    r.pool.filter(other=>other.id!==s.id).forEach(other=>{other.status="active";other.inPool=false;});\n    u.inPool=false;\n    r.pool=[u];\n    r.phase="fastestResult";\n    clearTimeout(r.timer);\n    r.winnerCelebrationUntil=Date.now()+10000;\n  }\n  emitState(s.data.room);\n });\n\n'''
s=s[:st]+new_listener+s[en:]
# error message
s=s.replace('Fastest Word must have a winner before the main quiz can start.', 'Fastest Finger Sequence Challenge must have a winner before the main quiz can start.')
p.write_text(s)

# player.js replace render + result handler
p=root/'public/player.js'; s=p.read_text()
st=s.index('function renderFastest(')
en=s.index('function showEliminationNotice', st)
new='''function renderFastest(pool,sequence,startAt,duration,difficulty,direction){\n const p=pool.find(x=>x.employeeCode===me);\n clearInterval(fastTimer);\n if(!p){\n   $("answers").innerHTML="";\n   $("status").innerHTML="⏳ <b>Waiting for the next Fastest Finger round.</b><br>You remain registered and may be selected in the next group of 7.";\n   return;\n }\n fastStarted=false;\n fastSeq=[]; fastIndex=0;\n const items=Array.isArray(sequence)?sequence:[];\n $("status").innerHTML="";\n $("answers").innerHTML=`\n   <section class="fastestPlayerStage sequenceChallengeStage" aria-label="Fastest Finger Sequence Challenge">\n     <div class="fastestPlayerKicker">⚡ FASTEST FINGER</div>\n     <h2>SEQUENCE CHALLENGE</h2>\n     <p class="fastestPlayerHint">Arrange the numbers in the correct order as quickly as possible.</p>\n     <div class="sequenceChallengeMeta"><span>DIFFICULTY: <b>${escapeHtml(difficulty||"HARD")}</b></span><span>ORDER: <b>${escapeHtml(direction||"LOWEST → HIGHEST")}</b></span><span>${items.length} NUMBERS</span></div>\n     <div class="fastestPlayerTimer" id="fastCountdown">GET READY</div>\n     <div class="fastPad sequencePad" id="sequencePad">${items.map((item,i)=>`<button type="button" class="fastKey sequenceKey" data-index="${i}" disabled>${item.value}</button>`).join("")}</div>\n     <div class="fastestPlayerProgress" id="fastProgress">SELECT THE LOWEST NUMBER FIRST</div>\n   </section>`;\n const buttons=[...document.querySelectorAll("#sequencePad .sequenceKey")];\n const setEnabled=v=>buttons.forEach(b=>b.disabled=!v);\n const submitSequence=(index)=>{\n   if(!fastStarted)return;\n   const btn=buttons[index]; if(!btn||btn.disabled)return;\n   btn.classList.add("pressed");\n   setTimeout(()=>btn.classList.remove("pressed"),120);\n   s.emit("fastest:submitSequence",{index:Number(index)});\n };\n buttons.forEach((btn,i)=>btn.addEventListener("click",()=>submitSequence(i)));\n setEnabled(false);\n const begin=()=>{\n   fastStarted=true;\n   setEnabled(true);\n   $("fastCountdown").textContent=`${(duration/1000).toFixed(1)}s`;\n   if($("fastProgress"))$("fastProgress").textContent=`⚡ START • LOWEST → HIGHEST • ${items.length} NUMBERS`;\n   clearInterval(fastTimer);\n   fastTimer=setInterval(()=>{\n     const remain=Math.max(0,startAt+duration-Date.now());\n     if($("fastCountdown"))$("fastCountdown").textContent=`${(remain/1000).toFixed(1)}s`;\n     if(remain<=0){\n       clearInterval(fastTimer);fastStarted=false;setEnabled(false);\n       if($("fastCountdown"))$("fastCountdown").textContent="⏱️ TIME UP";\n       if($("fastProgress"))$("fastProgress").textContent="TIME UP • WAIT FOR RESULT";\n     }\n   },50);\n };\n const wait=()=>{\n   const ms=Math.max(0,startAt-Date.now());\n   if($("fastCountdown"))$("fastCountdown").textContent=ms>0?`STARTING IN ${(ms/1000).toFixed(1)}s`:"GO!";\n   if(ms<=0)begin();\n };\n fastTimer=setInterval(wait,50);wait();\n}\n\ns.on("fastestSequenceResult",r=>{\n if(r.correct){\n   const index=fastIndex;\n   const buttons=[...document.querySelectorAll("#sequencePad .sequenceKey")];\n   // The server remains authoritative; progress count tells us which tile to lock.\n   if(Number(r.progress||0)>fastIndex){\n     const orderedValueButtons=buttons.filter(b=>!b.classList.contains("sequenceDone"));\n     const last=orderedValueButtons.find(b=>b.classList.contains("pressed"))||buttons.find(b=>!b.classList.contains("sequenceDone"));\n     if(last){last.classList.add("sequenceDone");last.disabled=true;}\n     fastIndex=Number(r.progress||fastIndex+1);\n   }\n   if($("fastProgress"))$("fastProgress").textContent=r.complete?`🏆 COMPLETE • ${(Number(r.elapsed||0)/1000).toFixed(2)} seconds`:`✓ CORRECT • ${Number(r.progress||0)} / ${Number(r.total||buttons.length)}`;\n   if(r.complete){\n     fastStarted=false;clearInterval(fastTimer);buttons.forEach(b=>b.disabled=true);\n     if($("fastCountdown"))$("fastCountdown").textContent=`🏆 ${(Number(r.elapsed||0)/1000).toFixed(2)}s`;\n   }\n }else{\n   if($("fastProgress"))$("fastProgress").textContent=`❌ WRONG ORDER • ${Number(r.progress||0)} / ${Number(r.total||8)} • TRY AGAIN`;\n   const buttons=[...document.querySelectorAll("#sequencePad .sequenceKey")];\n   const active=buttons.filter(b=>!b.classList.contains("sequenceDone"));\n   active.forEach(b=>{b.classList.remove("wrongKey");void b.offsetWidth;b.classList.add("wrongKey");});\n }\n});\n\n'''
s=s[:st]+new+s[en:]
# state call and text
s=s.replace('renderFastest(x.pool,x.fastestWordScrambled,x.fastestStartAt,x.fastestDurationMs,x.fastestWordLength);', 'renderFastest(x.pool,x.fastestSequence,x.fastestStartAt,x.fastestDurationMs,x.fastestSequenceDifficulty,x.fastestSequenceDirection);')
s=s.replace('Waiting for the host to start Fastest Word.', 'Waiting for the host to start Fastest Finger.')
s=s.replace('You won Fastest Word!', 'You won Fastest Finger!')
s=s.replace('Waiting for the next Fastest Word.', 'Waiting for the next Fastest Finger round.')
p.write_text(s)

# host.js labels and rendering
p=root/'public/host.js'; s=p.read_text()
s=s.replace('Fastest Word','Fastest Finger')
s=s.replace('FASTEST WORD','FASTEST FINGER')
s=s.replace('Fastest Word Times','Fastest Finger Times')
s=s.replace('SCRAMBLED WORD','SEQUENCE CHALLENGE')
s=s.replace('No players selected yet.','No players selected yet.')
# timer block: use sequence challenge title in host timer text
s=s.replace('`GET READY • ${(ms/1000-5).toFixed(1)}s`:`FASTEST FINGER • ${(ms/1000).toFixed(1)}s`', '`GET READY • ${(ms/1000-5).toFixed(1)}s`:`FASTEST FINGER • ${(ms/1000).toFixed(1)}s`')
# replace host fastest phase display block
old=''' if(x.phase==="fastest"){\n   const word=String(x.fastestWordScrambled||"");\n   const timerText=word?`🔤 SEQUENCE CHALLENGE: ${word} • ${x.fastestWordLength||word.length} LETTERS • MEDIUM`:"";\n   $("fastTimer").textContent=timerText;\n }\n'''
new=''' if(x.phase==="fastest"){\n   const items=Array.isArray(x.fastestSequence)?x.fastestSequence:[];\n   const timerText=items.length?`🔢 SEQUENCE CHALLENGE • ${x.fastestSequenceDifficulty||"HARD"} • ${x.fastestSequenceDirection||"LOWEST → HIGHEST"} • 15 SECONDS`:"";\n   $("fastTimer").textContent=timerText;\n }\n'''
if old in s:s=s.replace(old,new)
else:
 print('host phase block not found')
# results sort/status okay
p.write_text(s)

# tv.js replace fastest functions block
p=root/'public/tv.js'; s=p.read_text()
st=s.index('function progressFor(')
en=s.index('resolveScreen().then', st)
new='''function progressFor(x,employeeCode){return (x.fastestProgress||[]).find(p=>p.employeeCode===employeeCode)}\nfunction renderPlayerCard(p,pr){\n const progress=Number(pr?.sequence?.length||0);\n const total=Number(latestTvState?.fastestSequenceAnswer?.length||latestTvState?.fastestSequence?.length||8);\n const status=pr?.status||"READY";\n const time=pr?`${(Number(pr.time||0)/1000).toFixed(2)}s`:"—";\n return `<div class="ffCard ${status==="WRONG"?"wrongState":""}"><div class="ffName"><span>${escapeHtml(p.name)}</span><small>${escapeHtml(p.employeeCode)}</small></div><div class="ffSlots">${Array.from({length:total},(_,i)=>`<span class="letterSlot ${i<progress?"correctLetter":""}">${i<progress?"✓":i+1}</span>`).join("")}</div><div class="ffMeta"><b>${progress}/${total}</b><em>${status} ${time}</em></div></div>`;\n}\nfunction showFastest(x){\n const tvMain=$("tvmain"); if(!tvMain)return;\n clearInterval(fastTimer);\n const items=Array.isArray(x.fastestSequence)?x.fastestSequence:[];\n latestTvState=x;\n tvMain.innerHTML=`<div class="fastestScreen sequenceChallengeTv">\n   <div class="tvkicker">⚡ FASTEST FINGER</div>\n   <h1>SEQUENCE CHALLENGE</h1>\n   <div class="selectedCount">7 PLAYERS • ${escapeHtml(x.fastestSequenceDifficulty||"HARD")} • ARRANGE LOWEST → HIGHEST</div>\n   <div class="tvSequenceItems">${items.map((item,i)=>`<span style="--i:${i}">${item.value}</span>`).join("")}</div>\n   <div class="tvSequenceHint">Click the numbers in ascending order • First player to complete all ${items.length} wins</div>\n   <div class="ffGrid" id="ffGrid">${x.pool.map(p=>renderPlayerCard(p,progressFor(x,p.employeeCode))).join("")}</div>\n   <div class="tvTimer"><span id="tvSeconds">15.0</span><small>SECONDS</small></div>\n </div>`;\n const tickTimer=()=>{\n   const ms=Math.max(0,x.fastestStartAt+x.fastestDurationMs-Date.now());\n   if($("tvSeconds"))$("tvSeconds").textContent=(ms/1000).toFixed(1);\n   if(ms<=0)clearInterval(fastTimer);\n };\n tickTimer();fastTimer=setInterval(tickTimer,50);\n}\nfunction updateFastestProgress(x){\n if(x.phase!=="fastest"||!( $("ffGrid") ))return;\n latestTvState=x;\n $("ffGrid").innerHTML=x.pool.map(p=>renderPlayerCard(p,progressFor(x,p.employeeCode))).join("");\n}\n\n'''
s=s[:st]+new+s[en:]
p.write_text(s)

