p=root/'public/style.css'; s=p.read_text()
addon='''\n/* ===== Fastest Finger • Sequence Challenge ===== */\n.sequenceChallengeStage{width:min(820px,100%)!important;background:radial-gradient(circle at 50% 0%,rgba(227,198,106,.14),transparent 52%),linear-gradient(145deg,rgba(4,48,55,.94),rgba(2,22,30,.96))!important}\n.sequenceChallengeMeta{display:flex;justify-content:center;flex-wrap:wrap;gap:8px;margin:12px auto 20px}\n.sequenceChallengeMeta span{padding:7px 11px;border:1px solid rgba(227,198,106,.28);border-radius:999px;background:rgba(255,255,255,.05);color:#a9c7c4;font-size:10px;font-weight:850;letter-spacing:1px}\n.sequenceChallengeMeta b{color:#f1d36f}\n.sequencePad{width:min(720px,100%)!important;grid-template-columns:repeat(4,minmax(0,1fr))!important}\n.sequenceKey{min-height:92px!important;background:linear-gradient(145deg,#0a626a,#063a42)!important;border:2px solid rgba(227,198,106,.42)!important;box-shadow:0 12px 28px rgba(0,0,0,.28),inset 0 1px 0 rgba(255,255,255,.08);transition:transform .12s ease,box-shadow .2s ease,border-color .2s ease,opacity .2s ease}\n.sequenceKey:hover:not(:disabled){transform:translateY(-4px);border-color:#f1d36f!important;box-shadow:0 18px 38px rgba(0,0,0,.34),0 0 22px rgba(227,198,106,.16)}\n.sequenceKey.sequenceDone{background:linear-gradient(145deg,#1c805f,#0d5b4a)!important;border-color:#82e0b1!important;box-shadow:0 0 25px rgba(130,224,177,.20)}\n.sequenceKey.pressed{transform:scale(.95)}\n.sequenceKey.wrongKey{animation:sequenceWrong .25s ease!important;border-color:#ff6b7a!important}\n@keyframes sequenceWrong{50%{transform:translateX(7px);box-shadow:0 0 28px rgba(255,107,122,.22)}}\n.sequenceChallengeTv{padding:clamp(18px,3vw,40px)}\n.sequenceChallengeTv h1{font-size:clamp(42px,5.5vw,82px)!important;letter-spacing:-2px}\n.tvSequenceItems{display:flex;justify-content:center;flex-wrap:wrap;gap:clamp(8px,1.2vw,16px);margin:24px auto 16px}\n.tvSequenceItems span{min-width:clamp(74px,9vw,120px);height:clamp(78px,9vw,120px);display:grid;place-items:center;border-radius:20px;background:linear-gradient(145deg,#0b7277,#04383e);border:2px solid #e3c66a88;color:#fff;font-size:clamp(26px,3.8vw,48px);font-weight:950;box-shadow:0 18px 45px #0006;animation:sequenceTileTv .45s ease both;animation-delay:calc(var(--i)*45ms)}\n@keyframes sequenceTileTv{from{opacity:0;transform:translateY(18px) scale(.88)}to{opacity:1;transform:none}}\n.tvSequenceHint{margin:12px auto 22px;color:#b9d3d0;font-size:clamp(12px,1.5vw,17px);font-weight:750}\n@media(max-width:700px){.sequencePad{grid-template-columns:repeat(2,minmax(0,1fr))!important}.sequenceKey{min-height:74px!important}.sequenceChallengeMeta{gap:5px}.sequenceChallengeMeta span{font-size:9px;padding:6px 8px}}\n'''
if 'Sequence Challenge' not in s[-5000:]: s+=addon
p.write_text(s)

